class LRUCache {
  constructor(cap) { this.cap = cap; this.map = new Map(); }
  get(k) { if (!this.map.has(k)) return null; const v = this.map.get(k); this.map.delete(k); this.map.set(k, v); return v; }
  put(k, v) { this.map.set(k, v); if (this.map.size > this.cap) { const first = this.map.keys().next().value; this.map.delete(first); } }
}
